import { Helmet } from 'react-helmet-async';
// @mui
import { Grid, Button, Container, Stack, Typography } from '@mui/material';
// components
import Iconify from '../components/iconify';
import { BlogPostCard, BlogPostsSort, BlogPostsSearch } from '../sections/@dashboard/blog';
// mock
import POSTS from '../_mock/blog';
import { useMyContext } from './provider';

export default function BlogPage() {
  const { i18 } = useMyContext();
  const SORT_OPTIONS = [
    { value: 'latest', label: i18?.LISTINGPAGE?.LATEST || "Latest" },
    { value: 'popular', label: i18?.LISTINGPAGE?.POPULAR || "Popular" },
    { value: 'oldest', label: i18?.LISTINGPAGE?.OLDEST || "Oldest" },
  ];
  return (
    <>
      <Helmet>
        <title> Dashboard: Blog | Admin Panel </title>
      </Helmet>

      <Container>
        <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
          <Typography variant="h4" gutterBottom>
            {i18?.LISTINGPAGE?.BLOG || "Blog"}
          </Typography>
          <Button variant="contained" startIcon={<Iconify icon="eva:plus-fill" />}>
            {i18?.LISTINGPAGE?.NEW_POST || "New Post"}
          </Button>
        </Stack>

        <Stack mb={5} direction="row" alignItems="center" justifyContent="space-between">
          <BlogPostsSearch posts={POSTS} />
          <BlogPostsSort options={SORT_OPTIONS} />
        </Stack>

        <Grid container spacing={3}>
          {POSTS.map((post, index) => (
            <BlogPostCard key={post.id} post={post} index={index} />
          ))}
        </Grid>
      </Container>
    </>
  );
}
